package com.coffeeshop.service;import com.coffeeshop.dto.DiscountCommands;import com.coffeeshop.model.DiscountModels;import com.coffeeshop.repository.DiscountRepository;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;import static org.junit.jupiter.api.Assertions.*;class DiscountServiceTest{private final Stub repo=new Stub();private final DiscountService service=new DiscountService(repo);@Test void validatesAndNormalizes(){service.save(new DiscountCommands.Save(null," TEN "," Ten percent ","percentage",new BigDecimal("10"),null,null,true,null));assertEquals("TEN",repo.saved.code());assertEquals("PERCENTAGE",repo.saved.type());assertEquals(new BigDecimal("10.0000"),repo.saved.value());}@Test void rejectsInvalidValues(){assertThrows(IllegalArgumentException.class,()->save("PERCENTAGE","100.01"));assertThrows(IllegalArgumentException.class,()->save("FIXED_AMOUNT","-1"));assertThrows(IllegalArgumentException.class,()->save("OTHER","1"));}@Test void rejectsInvalidValidity(){LocalDateTime n=LocalDateTime.now();assertThrows(IllegalArgumentException.class,()->service.save(new DiscountCommands.Save(null,"D","D","FIXED_AMOUNT",BigDecimal.ONE,n,n,true,null)));}@Test void updateRequiresVersion(){assertThrows(IllegalArgumentException.class,()->service.save(new DiscountCommands.Save(1L,"D","D","FIXED_AMOUNT",BigDecimal.ONE,null,null,true,null)));}private void save(String t,String v){service.save(new DiscountCommands.Save(null,"D","D",t,new BigDecimal(v),null,null,true,null));}private static final class Stub implements DiscountRepository{DiscountCommands.Save saved;public List<DiscountModels.Discount>find(String s,Boolean a){return List.of();}public long save(DiscountCommands.Save q){saved=q;return 1;}public void setActive(long id,boolean a,byte[]v){}}}
